float PathScale = 0.7;
float PointScale = 0.01;

float PathWidth = 0.005;

vec3 PointBaseColor = vec3(0.631, 0.125, 0.514);
vec3 PathBaseColor = vec3(1.0, 1.0, 1.0) * 0.1;

vec3 Pass(vec2 SampleUv, int Iteration)
{
    float d = distance(vec2(sin(iTime)*PathScale, cos(iTime)*PathScale), SampleUv) - PointScale;
    float c = clamp(0.05/max(0.01, d), 0., 1.5);

    float PathD = distance(SampleUv, vec2(0.0, 0.0)) - PathScale;

    if (PathD > PathWidth || PathD < -PathWidth)
    {
    return PointBaseColor * c;
    }

    return PointBaseColor * c + (PathBaseColor * max(d, 0.0));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    uv -= 0.5;
    uv *= 2.;
    uv.x *= iResolution.x / iResolution.y;

    // holds the color vales from antialiasing.
    vec3 ColorValues[9];

    // antialiasing offsets.
    vec2 Offsets[9];
    Offsets[0] = vec2(-0.707, 0.707);
    Offsets[1] = vec2(0.0, 1.0);
    Offsets[2] = vec2(0.707, 0.707);
    Offsets[3] = vec2(-1.0, 0.0);
    Offsets[4] = vec2(0.0, 0.0);
    Offsets[5] = vec2(1.0, 0.0);
    Offsets[6] = vec2(-0.707, -0.707);
    Offsets[7] = vec2(0.0, -1.0);
    Offsets[8] = vec2(0.707, -0.707);

    vec3 Color = vec3(0.0, 0.0, 0.0);

    for (int i = 0; i < 9; i++)
    {
    Color += Pass(uv + Offsets[i]*0.000741, i) * 0.111;
    }

    fragColor = vec4(Color,1.0);
}
